var e={"29268u":`RoboKit — construye y simula un coche robot`,qvztjl:`RoboKit — inicio del tutorial`,s42iv2:`academe.com.br (se abre en una pestaña nueva)`,"16us7mj":`Idioma`,ktdb8o:`Ajustes`,"198kuu7":`Banco de trabajo 3D`,ia581p:`Animación`,j4z771:`Pausa`,wlqobg:`Pausa (Espacio)`,h23ysv:`Velocidad de reproducción`,r953rm:`Zoom`,"19blqjd":`Acercar`,"110wpq2":`Alejar`,q5w460:`Vista`,bldqt5:`Vista despiezada (E)`,"44cnpg":`Vista de persecución: seguir el coche desde atrás (C)`,"13epjbk":`Mapa cenital de la pista de pruebas`,j4zjee:`El obstáculo seleccionado`,yq1vr3:`Del centro del obstáculo, desde el centro de la pista, donde el coche arranca mirando hacia arriba del mapa`,"19kd62s":`Personalizar la pista`,l1a70i:`Personalizar la pista: mover, girar y redimensionar los obstáculos`,"15n0apn":`Deshacer el último cambio (Ctrl+Z). Ctrl+Shift+Z lo rehace`,j4uzpn:`La pista tal como venía, con el coche de vuelta en su salida`,"84sbk0":`Dejar la pista como estaba (Esc)`,"1oy9vz":`Usar esta pista: la vista 3D se reconstruye y la simulación continúa`,ium5z9:`Cómo decide el programa del coche`,vq0gg8:`Cerrar el diagrama de flujo`,s2tc63:`Cerrar (Esc)`,"13bjj4d":`Poner el coche en Auto y verlo decidir`,gfubiu:`Cómo decide el programa: abrir el diagrama de flujo`,"1gh0at8":`Pasos del tutorial`,"61nq88":`Pasos anteriores`,ga5x9q:`Pasos siguientes`,"1v1ybkn":`Conducir`,"9anomo":`Adelante (W / ↑)`,bbake2:`Girar a la izquierda (A / ←)`,bfl95g:`Parar (Espacio)`,iseiwq:`Girar a la derecha (D / →)`,"4o292l":`Atrás (S / ↓)`,"10qzszt":`Velocidad de los motores`,"2yhdcy":`Modo de conducción`,"8m10x9":`Manual (1)`,"1ogxhr7":`Evitar obstáculos (2)`,"1i3ygcv":`Desactivar motores (3)`,"1dlx0na":`Zumbador (B)`,isqcd9:`Ángulo del servo`,"29ulgm":`Salida serie`,"1l0xxoj":`Cerrar`,"2r1h4p":`Conexión`,cwepyb:`Cargando…`,"10iu545":`RoboKit necesita JavaScript para funcionar.`,"120y7gz":`Diseñado por`,"1hpelzf":`Placa`,"1j2fqe6":`BANCO DE TRABAJO`,"17d8vhd":`Paso 1 · Reúne las piezas`,gqo5v1:`Simulador`,"1py6ulk":`Haz clic para inspeccionar`,"1ms3o1u":`Distancia`,"2w2xwg":`Velocidad`,n44ilu:`Modo`,"1d2vfr6":`Servo`,"152va0w":`Simulación en pausa`,"11i7yk1":`Haz clic en un obstáculo para seleccionarlo.`,"1a4x3zw":`Tamaño`,"1kpdcfp":`Largo`,gfxz9b:`Ancho`,s3robe:`Diámetro`,"7puwki":`Alto`,kbxnhn:`Giro`,"7nkn2r":`Posición, desde la salida`,v1hcj2:`Adelante`,"1vf2pel":`A la derecha`,"1xakelj":`Mayús`,"1esrfu8":`pasos de 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`tamaño desde el centro`,"1xzs12p":`mover ·`,"14bbmnu":`girar`,g7xa5b:`Pista · 3 × 3 m`,vmlwpb:`Deshacer`,"2zps2o":`Restablecer`,ew9em3:`Cancelar`,lewgh4:`Guardar`,"1vz8dhj":`Cómo decide el programa`,m76rx7:`Elige una caja para ver su código`,"1hnif0x":`Flujo del programa`,"11rknnz":`En vivo`,"540b06":`Auto`,"1fr6xqr":`Reúne las piezas`,"1wu7r43":`Manual`,ky4lc5:`Parar`,"152av8f":`Actuadores`,"1df7dln":`Zumbador`,pksfl2:`conducir ·`,"1hrh82t":`Espacio`,"9zyeew":`parar ·`,jw8yab:`modo ·`,j4ckle:`zumbador ·`,kzo6rh:`persecución`,mcpijf:`Monitor serie`,"1aeugy":`Borrar`,"1jgmzoq":`← Atrás`,c9ljxw:`pasos`,"1padbm0":`Siguiente`,g6g542:`Volver al paso`,"1k7z1pa":`Esc`,dpexcn:`Especificaciones`,"8f4gnm":`Ir al paso`,qy3p54:`AJUSTES`,"12znfuf":`El paso de conducción se conecta a`,"17rhf7d":`Coche real (Wi-Fi del ESP32)`,dsq8ip:`Dirección del coche`,"1ihj7t4":`Pantalla y sonido`,oh792y:`Reproducir el zumbador por los altavoces`,"1bxmuya":`Mostrar el haz ultrasónico`,"1gxdv01":`La cámara sigue al coche`,"9mmtn3":`Reiniciar la simulación`,"1k6e5zv":`Aplicar`,"1iptqu5":`URL no válida «{url}»`,"12bfr2h":`La URL debe empezar por ws:// o wss://`,"1s22nop":`Conectando a {url}`,"1q17yrm":`Reintentando en {s} s`,hsi0bv:`No llegan datos del coche`,ye8ewg:`Conectado`,"1puhp9v":`Conectando…`,y1y3f2:`Sin datos`,ci4tze:`Desconectado`,"1fmx9lv":`Error de conexión`,"19wtqq3":`Conectado · {board}`,"1b4ym3j":`Simulador integrado`,bgnl0z:`Preparando los gráficos`,"39rjx0":`Listo`,"1ruee97":`El banco 3D no pudo arrancar. Necesita WebGL: prueba con otro navegador o activa la aceleración por hardware.`,xa5swu:`PISTA DE PRUEBAS`,"18xfupg":`Conduce con los controles de la derecha`,khccvm:`Conduce con W A S D o con los controles de la derecha`,vhwww6:`Paso {n} · {title}`,"1i98668":`Montando el coche`,y9b5jm:`Colocando las piezas`,qzfxj5:`Mostrar la línea {n} en el banco`,pj86x7:`Mostrar esto en el banco`,"13bzcw5":`Copiado`,"8gdme8":`Selecciona y copia`,s6g5lw:`Copiar`,"1bstp0v":`Lista de materiales`,"1g4j0cl":`Necesitarás`,"15cdqf0":`Herramientas`,"1wrxvmg":`Haz esto`,"1x0ptmh":`Mapa de pines · {board}`,"1go9otx":`Sketches`,zvnhd5:`Sketch`,t8quxl:`Descargar`,na9qmv:`Si algo falla`,"5mau71":`Nota`,"1xh5jos":`{kicker} · Paso {n} de {total}`,slbawy:`Siguiente: {step} →`,"7rhhil":`Empezar de nuevo ↺`,"1mtyvb1":`Paso {n}: {step} · {done} / {total} marcados`,"4x1xaj":`Paso {n}: {step}`,d2gue0:`Caja de cartón`,"1xebpbq":`Bloque de madera`,hi63vm:`Lata`,"14yz9o9":`Maceta`,"1g6nbya":`Tiene que quedar dentro de las paredes.`,v23nvk:`El lugar de salida del coche tiene que quedar libre.`,"1d1sqge":`El coche está ahí.`,sjcnug:`Dos obstáculos no pueden ocupar el mismo sitio.`,"1rjq9tt":`Arrastra un obstáculo para moverlo. Sus tiradores cuadrados cambian su tamaño y el redondo lo gira.`,qaws2z:`La pista vista desde arriba. Haz clic en un obstáculo para seleccionarlo y arrástralo para moverlo. Con el teclado: Av Pág y Re Pág seleccionan un obstáculo, las flechas lo mueven y R lo gira.`,km6rtw:`Obstáculo`,v6zgjh:`La pista tal como venía. Al guardar, el coche vuelve a su salida.`,"1bneya5":`Cada vuelta empieza aquí`,"1gvmqkj":`Decisión`,"2wk0tb":`Acción`,ltbyq8:`sí`,r90oai:`no`,"10pfeta":`{file} · líneas {lines}`,"1mv69ab":`{file} · línea {lines}`,v5glvz:`sin eco`,"1y6bn7c":`izquierda {left} · derecha {right}`,"17yvayv":`Camino libre: sigue adelante`,g8loky:`{reading} delante · para a menos de {stop} cm`,"1qpxp29":`Parar · LED encendido · pitido`,lman68:`obstáculo a {reading} · menos de {stop} cm`,"4e4gg4":`Ha retrocedido: mira alrededor`,"1x1kke3":`la lectura no había cambiado en {s} s`,"1pc4lzp":`Ha dado marcha atrás: mira otra vez`,"11qad25":`los dos lados eran demasiado estrechos para girar`,dfsfd7:`Atascado: retrocediendo`,eic5lt:`lectura sin cambios durante {s} s`,n7w5mt:`Sin espacio para girar: marcha atrás`,etina8:`{sides} · menos de {tight} cm`,crgp5w:`Mirando a la derecha`,vto9jk:`lee {reading}`,"1xubspn":`Mirando a la izquierda`,"92dcjq":`derecha {right} · izquierda lee {reading}`,cfs13v:`¿Hay espacio para girar?`,h7zzeh:`{sides} · necesita {tight} cm`,qlw2zr:`Girando otra vez a la izquierda`,"1fd6gkc":`Girando otra vez a la derecha`,"1hj21ci":`bloqueado justo después de un giro: mismo sentido`,"1jk1kpr":`Girando a la izquierda`,u6ps9c:`Girando a la derecha`,"1uvg70v":`Auto está desactivado`,"1bbdvwo":`Vista en vivo: solo el coche simulado`,"1fj8dwo":`activa Auto para ver al coche decidir`,"14g7i3l":`un coche real informa de sus lecturas, no del paso de su rutina`,"15nlm70":`Volver al paso {n} · {step}`,"1i8tm8j":`Se monta en <b>este paso</b>`,rpu2qi:`Se monta en el <b>paso {n} · {step}</b>`,"1b4o3fw":`Ir al paso {n} →`,y322vs:`Idioma: {name}`,bk85tv:`Reproducir`,"1x4eyna":`{action} (Espacio)`,gpdo6z:`Usa una dirección ws:// o wss://, p. ej. ws://192.168.4.1:81/`,"1iquufv":`Conéctate primero a la red Wi-Fi del coche. Consulta README.md para ver el formato de mensajes que debe usar el firmware.`,njqkz2:`Escribe una URL de WebSocket, p. ej. ws://192.168.4.1:81/`,nrzvmi:`Conduce un coche simulado por una pista de pruebas, sin necesidad de hardware.`,cegybp:`Piezas`,wv4sck:`Prepárate`,"7z3mbb":`Todo lo necesario para un rover de cuatro ruedas con una «cabeza» ultrasónica que puede mirar a su alrededor. Coloca las piezas así y márcalas una a una. Pasa el ratón por una fila para encontrarla en la alfombrilla, o haz clic en una pieza para ver sus detalles.`,"1x97es5":`Carga las celdas 18650 en un cargador de Li-ion adecuado antes de empezar, y usa celdas protegidas: una celda sin protección puede entregar decenas de amperios en un cortocircuito.`,"13wu8qd":`Chasis acrílico: placa inferior, intermedia y superior`,"9z9vwl":`Motores reductores TT (3–6 V, 1:48) con 8 soportes acrílicos en forma de T, 8 pernos M3 × 30 y tuercas`,"1qr4ely":`Ruedas, 65 mm`,cmzolq:`Módulo driver de dos motores L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + cable USB`,"15cdntm":`ESP32 DevKit V1 (30 pines) + placa de expansión + cable USB`,mfnvxi:`Sensor ultrasónico HC-SR04 + su soporte para servo y tornillos`,"15iavp3":`Microservo SG90 con brazos y tornillos`,"1allzrf":`Celdas Li-ion 18650 (protegidas) + portapilas de 2 posiciones en serie con cables`,xooybo:`Interruptor deslizante, LED rojo de 10 mm, resistencia de 220 Ω, zumbador activo de 5 V`,"1csc29i":`Interruptor deslizante, LED rojo de 10 mm, zumbador activo de 5 V, transistor NPN (PN2222A o S8050), resistencias de 220 Ω, 2 × 1 kΩ y 2 kΩ`,"17dpcif":`Clavija DC de barril con bornes de tornillo, 5.5 × 2.1 mm`,bozwcy:`20 cables dupont hembra–hembra de 15 cm; cable de conexión rojo y negro; 16 separadores de latón M3 hembra–hembra (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 tornillos M3 × 6 mm, cinta de espuma, tubo termorretráctil`,"5z6ae7":`Soldador, estaño`,"1xhh6dp":`cables de los motores, el interruptor, los cables del LED y del zumbador`,"11dguvz":`Destornilladores pequeños`,"1b1pnob":`de estrella para los tornillos M3, plano para los bornes del driver y de la clavija`,"1ligzav":`Alicates de corte / pelacables`,"3pb5yx":`cortar y pelar el cable de conexión y los cables dupont`,"1avt53n":`Multímetro`,"1slxnnr":`comprobar la polaridad antes de dar corriente`,"100w2b7":`Cargador de Li-ion`,"64j96q":`para las celdas 18650`,"1heknmc":`Ordenador, Arduino IDE`,"1mo2nzj":`para subir el código en el paso 9`,t9gk37:`Motores`,"15i6udf":`Montaje`,"1fofbt3":`Motores y ruedas`,"15llile":`Cada motor TT es un pequeño motor DC que mueve una reductora de plástico 1:48. Los dos motores de la izquierda y los dos de la derecha giran siempre juntos, como las orugas de un tanque: el coche gira haciendo ir los dos lados a velocidades distintas.`,k5fimq:`El rojo en la lengüeta interior de cada motor es lo que te permite unir rojo con rojo en el paso 4: el motor delantero y el trasero de un lado están enfrentados, así que sus lengüetas interiores cumplen la misma función. Las lengüetas son finas y se rompen si se tira de un cable, así que pega con cinta cada par de cables a su motor. Los cables quedan de pie en el centro para que la ranura larga de la placa intermedia pueda bajar sobre ellos en el paso 3.`,"7fte4n":`Placa inferior`,rbcm1a:`Motores reductores TT`,sjfn38:`Soportes acrílicos de motor en forma de T`,"732lu":`Pernos M3 × 30 y tuercas`,skq14t:`Ruedas`,"1s4rmq":`Coloca los cuatro motores en la placa inferior, en su sitio, con los ejes hacia fuera y los extremos del motor hacia el centro. Suelda dos cables de unos 15 cm a cada uno: el rojo en la lengüeta más cercana al centro del coche y el negro en la más cercana a la rueda. Deja los ocho cables de pie juntos en el centro de la placa.`,"1mrwedd":`Levanta la placa. Desde abajo, mete un soporte hacia arriba por la ranura del lado interior de cada motor y otro en la muesca del borde de la placa, por fuera. Pasa dos pernos M3 × 30 por soporte, reductora y soporte, con las cabezas del lado de la rueda, y aprieta una tuerca en cada uno.`,"13sq8kw":`Encaja una rueda en cada eje. El eje tiene dos caras planas que encajan en el buje, así que la rueda no puede patinar sobre él.`,"199dyzl":`Placas`,qr73r6:`Apila las placas`,kig8cy:`Los separadores de latón elevan la placa intermedia 25 mm sobre la inferior, por encima de las reductoras de 22 mm de alto, y dan a la electrónica un suelo plano. Cada separador tiene rosca en los dos extremos: un tornillo sube a través de la placa de abajo y otro baja a través de lo que vaya encima.`,"1w8a39y":`El acrílico se agrieta si lo aprietas demasiado: basta con que quede firme. Los chasis varían: si el tuyo no tiene agujero donde lo necesita el controlador, dos separadores y una almohadilla de cinta de espuma bajo el otro extremo sujetan bien una placa.`,jcqip:`Placa intermedia`,u6l9bq:`Separadores de latón M3 × 25 mm`,"4cdagt":`Separadores de latón M3 × 10 mm (para el controlador)`,xaqs1y:`Separadores de latón M3 × 15 mm (para la placa superior)`,"300byl":`Tornillos M3 × 6 mm`,tezznv:`Atornilla ocho separadores de 25 mm a la placa inferior, cuatro a cada lado, cada uno con un tornillo metido desde abajo.`,"70hnlv":`Antes de poner la placa intermedia, mientras aún llegas por debajo, fija los cuatro separadores de 10 mm bajo los agujeros de montaje del controlador (sujeta la placa en su sitio para ver qué agujeros coinciden) y los cuatro separadores de 15 mm en las esquinas de su mitad trasera, cada uno con un tornillo desde abajo.`,"1tynoxv":`Baja la placa intermedia sobre los separadores de 25 mm, pasando los cables de los motores hacia arriba por la ranura larga del centro mientras baja, y atorníllala.`,"1n5adbz":`Driver`,"1ri406w":`Monta el driver de motores`,"5n5nar":`Un pin de microcontrolador no debería dar más de unos 20 mA, pero un motor TT consume unos cientos de mA al avanzar y más de 1 A bloqueado. El módulo L9110S tiene dos puentes H que conmutan la corriente de la batería a través de los motores y pueden invertirla.`,"1uicxnj":`Qué tornillo de un borne recibe cada par aún no importa: la prueba de cableado del paso 9 muestra si un lado gira al revés o si una rueda gira contra su compañera. Deja libre la tira de 6 pines (B-IA, B-IB, GND, VCC, A-IA, A-IB): la alimentación se conecta en el paso 7 y las señales en el paso 8. El L9110S aguanta 800 mA por canal y aquí cada canal mueve dos motores: suficiente para conducir con normalidad, pero no mantengas las ruedas bloqueadas. Si los chips se calientan, un módulo TB6612FNG (1.2 A por canal) es un cambio más robusto.`,utkklb:`Almohadilla de cinta de espuma de doble cara`,syij08:`Pega el driver a la placa intermedia con cinta de espuma, delante de los separadores del controlador y a la izquierda del centro: la tira de 6 pines hacia el borde izquierdo del coche y los bornes de tornillo hacia el centro del coche.`,"15kkcap":`Dobla los cables hacia delante por la placa y llévalos hasta los bornes del driver. Retuerce juntos los dos cables rojos de los motores izquierdos y juntos sus dos cables negros, y atornilla los dos pares en MOTOR-A, el borne más cercano al controlador. Haz lo mismo con los cables de los motores derechos en MOTOR-B.`,"18rvg69":`Controlador`,ync8b9:`Monta el Arduino UNO`,"1u68uls":`Monta el ESP32`,ertyxs:`El Arduino UNO (ATmega328P, 16 MHz, lógica de 5 V) ejecuta tu sketch. Encima se enchufa un Sensor Shield V5 que da a cada pin su propia tira G / V / S (tierra, 5 V y señal), porque la tira de alimentación del UNO solo tiene un pin de 5 V para compartir entre el servo y el sensor.`,"1p7bu2t":`El ESP32 (doble núcleo, hasta 240 MHz, Wi-Fi y Bluetooth, lógica de 3.3 V) ejecuta tu sketch y deja que RoboKit conduzca el coche real por Wi-Fi. Su placa de expansión añade una toma DC con regulador y una tira G / V / S para cada pin.`,ii2aq7:`Los pines del UNO son de 5 V, así que el sensor y el servo se conectan directamente al shield.`,"1ghuj2z":`Los pines del ESP32 funcionan a 3.3 V y no toleran 5 V, así que la salida Echo del sensor lleva un divisor de tensión en el paso 8.`,t5ws5g:`ESP32 DevKit V1 (30 pines)`,"1tu8qz5":`Placa de expansión ESP32 (30 pines)`,"14w4gx0":`Atornilla el UNO sobre los cuatro separadores de 10 mm detrás del driver, con sus tomas USB y DC hacia el lado izquierdo del coche.`,hw767j:`Encaja el Sensor Shield V5 sobre el UNO con cada pin en su zócalo. Deja puesto el jumper SEL, para que los pines V del shield tomen 5 V del UNO, y no conectes nada al borne de tornillo del shield.`,"1opbgrl":`Atornilla la placa de expansión sobre los cuatro separadores de 10 mm detrás del driver, con su toma DC hacia el lado izquierdo del coche.`,"1xxnsy2":`Asienta el DevKit en los dos zócalos de modo que cada nombre de pin coincida con el nombre impreso junto al zócalo. Una placa desplazada un pin pone la alimentación en los pines equivocados.`,ua2sfx:`Pon el jumper de los pines V en 5 V, porque el servo, el HC-SR04 y el zumbador necesitan 5 V. Las placas de expansión varían, así que comprueba las marcas del jumper en la tuya.`,"1jzloyj":`Sensor`,"19ot7f3":`Cabeza del sensor`,jii9ss:`El HC-SR04 emite una ráfaga ultrasónica de 40 kHz y cronometra el eco: distancia en cm ≈ tiempo del eco en µs ÷ 58. Mide de 2 cm a unos 4 m dentro de un haz de unos 15° de ancho. Montado sobre un servo SG90, puede mirar a izquierda y derecha antes de que el coche gire.`,"1s5nsw8":`Para centrar el servo, conéctalo a la tira A5 del shield (marrón en G) y sube cualquiera de los dos sketches del paso 9: ambos dejan la cabeza a 90°. Girar el eje de salida a la fuerza puede romper sus engranajes de plástico. Montado con esta orientación, los pines del sensor son GND, Echo, Trig, VCC de izquierda a derecha, vistos de frente.`,"3b6msg":`Para centrar el servo, conéctalo a la tira GPIO 23 (marrón en G, V a 5 V) y sube el firmware del paso 9, cuyo setup() llama a servoWrite(90). Girar el eje de salida a la fuerza puede romper sus engranajes de plástico. Montado con esta orientación, los pines del sensor son GND, Echo, Trig, VCC de izquierda a derecha, vistos de frente.`,"2934zx":`Microservo SG90, brazo simple y tornillos`,"1o4q0ha":`Soporte de servo para el HC-SR04, con sus tornillos`,"87cfw2":`Sensor ultrasónico HC-SR04`,"1bhe6w2":`Sujeta el servo sobre el hueco rectangular de la parte delantera de la placa intermedia, con el eje de salida hacia arriba y en la línea central del coche. Pasa su conector hacia abajo por el hueco, hacia atrás bajo la placa y hacia arriba por la ranura pequeña de detrás, y tira del cable hasta que el conector quede sobre la placa junto al controlador. Luego baja el servo al hueco, con el cable por la muesca de su extremo, empuja el cable sobrante bajo la placa, lejos del eje del motor, y atornilla las dos orejas del servo a la placa.`,"7x26fs":`Centra el servo y luego encaja un brazo simple en su eje, apuntando hacia delante, y fíjalo con el tornillo del brazo.`,"3f8bcm":`Atornilla el soporte al brazo, vertical y hacia delante.`,"178kb38":`Atornilla el HC-SR04 a la parte delantera del soporte por los dos agujeros de las esquinas de un borde largo, con ese borde abajo y los pines arriba: así sus cables salen hacia arriba, lejos del servo.`,"1jamndy":`Alimentación`,tboesy:`Dos celdas 18650 en serie dan 7.4 V nominales (8.4 V llenas, unos 6 V descargadas). El interruptor corta el cable + de la batería. Todo se une en una clavija DC con bornes de tornillo: los dos cables de la batería entran en ella, la clavija alimenta el UNO por su toma DC, cuyo regulador genera los 5 V de la lógica, y dos cables más desde los mismos bornes alimentan el driver de motores. El driver no puede tomar su alimentación de los pines de 5 V del shield: vienen del pequeño regulador del UNO, que cuatro motores sobrecargarían. Las piezas que necesitan cables soldados los reciben en el banco, antes de ir al coche: pasa primero un trozo de termorretráctil por el cable y luego contráelo sobre la soldadura.`,r69l9i:`Dos celdas 18650 en serie dan 7.4 V nominales (8.4 V llenas, unos 6 V descargadas). El interruptor corta el cable + de la batería. Todo se une en una clavija DC con bornes de tornillo: los dos cables de la batería entran en ella, la clavija alimenta la placa de expansión por su toma DC, cuyos reguladores generan los 5 V y 3.3 V de la lógica, y dos cables más desde los mismos bornes alimentan el driver de motores. El driver no puede tomar su alimentación de los pines de 5 V de la placa: vienen de su pequeño regulador, que cuatro motores sobrecargarían. Las piezas que necesitan cables soldados los reciben en el banco, antes de ir al coche: pasa primero un trozo de termorretráctil por el cable y luego contráelo sobre la soldadura.`,"175zcey":`Comprueba dos veces la polaridad antes de meter las celdas: la toma del UNO tiene el positivo en el centro, y el borne + de la clavija es su pin central (compruébalo con un multímetro). Recarga cuando el pack baje a unos 7 V, por debajo de los cuales el regulador del UNO no puede mantener 5 V. Si no se enciende ningún LED, apaga enseguida y revisa el cableado antes de volver a probar. El LED y el zumbador se quedan en el banco hasta el paso 8.`,t60ux3:`Comprueba dos veces la polaridad antes de meter las celdas: la mayoría de las placas de expansión tienen el positivo en el centro, pero mira el símbolo junto a la toma, y el borne + de la clavija es su pin central (compruébalo con un multímetro). Recarga cuando el pack baje a unos 7 V. Si no se enciende ningún LED, apaga enseguida y revisa el cableado antes de volver a probar. El LED y el zumbador se quedan en el banco hasta el paso 8.`,mvli44:`Placa superior + 4 tornillos M3 × 6 mm`,"1dowjmo":`Portapilas 2 × 18650 con cables, 2 celdas`,"83x4u2":`Interruptor deslizante`,"1in9b4e":`Clavija DC de barril con bornes de tornillo (centro +)`,l8wrh1:`LED rojo de 10 mm + resistencia de 220 Ω`,"24gtky":`Zumbador activo de 5 V`,"14zuroc":`Zumbador activo de 5 V, transistor NPN + resistencia de 1 kΩ`,"1pgj6ai":`Cinta de espuma, termorretráctil, 4 cables dupont para cortar: 2 rojos, 2 negros`,"1ewjpxi":`Cinta de espuma, termorretráctil, 5 cables dupont para cortar: 2 rojos, 2 negros, 1 naranja`,y2bs3a:`Coloca la placa superior sobre los cuatro separadores de 15 mm y atorníllala.`,anc24f:`En el banco, corta el cable rojo del portapilas a unos 2 cm del portapilas. Suelda el extremo del portapilas a un pin exterior del interruptor, y 10 cm del trozo cortado al pin central.`,"1mixan6":`Sujeta el portapilas sobre la placa superior, con sus cables hacia la izquierda del coche. Pasa el cable negro hacia abajo por el agujero del borde izquierdo de la placa y llévalo hacia delante por la placa intermedia mientras bajas el portapilas. Pega el portapilas con dos tiras de cinta de espuma, y el interruptor de lado en el borde izquierdo de la placa, con la palanca hacia fuera. Luego lleva el cable rojo hacia delante, por la esquina delantera de la placa. Los dos cables deben acabar junto a la toma DC del controlador.`,"1xim7b6":`Corta un cable dupont rojo y uno negro a 12.5 cm de un extremo. Encaja el conector del trozo rojo largo en el pin VCC del driver y el del negro largo en GND, y llévalos hacia atrás por el borde izquierdo de la placa intermedia hasta la toma.`,"1200i":`Corta un cable dupont rojo y uno negro a 11 cm de un extremo. Encaja el conector del trozo rojo largo en el pin VCC del driver y el del negro largo en GND, y llévalos hacia atrás por el borde izquierdo de la placa intermedia hasta la toma.`,"1nymzxl":`Pela 5 mm de los cuatro extremos sueltos. Atornilla los dos rojos bajo el tornillo + de la clavija y los dos negros bajo el −, y luego mete la clavija en la toma DC del UNO, girada para que el + quede arriba.`,f3jc5e:`Pela 5 mm de los cuatro extremos sueltos. Atornilla los dos rojos bajo el tornillo + de la clavija y los dos negros bajo el −, y luego mete la clavija en la toma DC de la placa de expansión, girada para que el + quede arriba.`,hhvzfi:`En el banco, suelda la resistencia de 220 Ω en serie con la pata larga (+) del LED. Corta por la mitad un cable dupont rojo y uno negro. Suelda una mitad roja al extremo libre de la resistencia y una mitad negra a la pata corta del LED.`,"1qz1083":`Dobla planos los dos pines del zumbador. Suelda la otra mitad roja al + (el pin más largo, marcado arriba) y la otra mitad negra al −.`,"110bbxt":`Dobla planos los dos pines del zumbador y suelda la otra mitad roja al + (el pin más largo, marcado arriba). Suelda el colector del transistor al pin − y una resistencia de 1 kΩ a su base; luego media dupont naranja a la resistencia y la otra mitad negra al emisor. Contrae un mismo tubo sobre el transistor y la resistencia. Comprueba en la hoja de datos de tu transistor qué pata es cada una.`,"1avlub7":`Comprueba que ninguna soldadura desnuda pueda tocar otra y que el interruptor esté apagado. Luego pon las dos celdas en el portapilas, cada extremo + donde el portapilas indica +. Enciende un momento: deben encenderse los LED de alimentación del controlador y del driver.`,k2hc2b:`Cableado`,s234wa:`Cablea el coche`,"1po8toc":`Cada sensor y actuador se conecta a una tira G / V / S del shield, así que todos comparten la tierra del UNO; la tierra del driver viene de la batería, que es la misma tierra a través de la toma DC. Los pines se eligen según dónde está cada pieza, así que los cables salen en abanico de las tiras sin cruzarse. Trabaja en este orden, con el interruptor apagado: primero el LED, abajo en el extremo izquierdo de la tira, y los cuatro cables del sensor al final, porque pasan en arco por encima de todo lo demás. Un cable dupont se pone extremo a extremo: encaja bien un conector en su pin, dobla el cable y encaja el otro. Pasa el ratón por una fila para ver el cable en el modelo.`,"1ylwoyd":`Cada sensor y actuador se conecta a una tira G / V / S de la placa de expansión, así que todos comparten la tierra del ESP32; la tierra del driver viene de la batería, que es la misma tierra a través de la toma DC. Los pines se eligen según dónde está cada pieza, así que los cables salen en abanico de las tiras sin cruzarse. Trabaja en este orden, con el interruptor apagado: primero el LED, abajo en el extremo izquierdo de la tira, y los cables del sensor al final, porque pasan en arco por encima de todo lo demás. Un cable dupont se pone extremo a extremo: encaja bien un conector en su pin, dobla el cable y encaja el otro. Pasa el ratón por una fila para ver el cable en el modelo.`,"10tvb2g":`D5 y D11 llevan la velocidad de cada lado: son pines PWM que siguen funcionando mientras se usa la librería Servo (que toma el Timer1, lo que desactiva el PWM en D9 y D10). D6 y D12 llevan la dirección. El servo y el zumbador usan A5 y A0 como pines digitales normales. Todos los pines G están unidos, y también todos los pines V: el GND y el VCC del sensor pueden ir en los que queden más cerca.`,it0an4:`El divisor de 1 kΩ / 2 kΩ convierte el pulso Echo de 5 V en 3.3 V (5 V × 2 ⁄ 3). Echo usa el GPIO 35, uno de los pines solo de entrada (34–39): leer es todo lo que tiene que hacer. El zumbador se alimenta del pin V de 5 V y el transistor lo conmuta, porque 3.3 V está por debajo de lo que necesita un zumbador de 5 V. Las salidas evitan los GPIO 0, 2, 5, 12, 14 y 15, que son pines de arranque o emiten pulsos mientras arranca el ESP32. Todos los pines G están unidos, y también todos los pines V.`,"16ffufp":`LED: pégalo junto a la esquina delantera izquierda del controlador · rojo → S · negro → G`,"55vkwv":`Driver A-IA / A-IB (izquierda)`,"1wr2rcy":`Driver B-IA / B-IB (derecha)`,"12y58k1":`Cable del servo (marrón G, rojo V, naranja S)`,"1xjcvwz":`Zumbador: pégalo en la parte delantera de la placa superior · rojo → S · negro → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G de D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Zumbador: pégalo en la parte delantera de la placa superior · rojo → V · naranja (base) → S · negro (emisor) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G de GPIO 34`,"1ig2p4r":`HC-SR04 Echo: corta su dupont a 4.5 cm de un extremo · 1 kΩ entre los trozos · 2 kΩ hacia un trozo de 4.7 cm cortado del extremo de un dupont negro · trozos cortos → S y G`,xoaiok:`Código`,"1if8prf":`Programa`,"1g03ums":`Sube el código`,"1bv2ey7":`Dos sketches. La prueba de cableado recorre cada pieza por turno, para que veas que cada una está conectada y que los dos lados giran en el sentido correcto. El evitador de obstáculos es el programa del coche: avanza hasta que algo está a menos de 22 cm, mira a derecha e izquierda con la cabeza y gira hacia el lado con más espacio.`,"8lzj5q":`Este firmware convierte el ESP32 en un punto de acceso Wi-Fi. Ejecuta las órdenes que envía RoboKit (conducción, velocidad, modo, servo, LED y zumbador), se para si dejan de llegar y devuelve la distancia y el estado de los motores 10 veces por segundo. En el modo Auto evita obstáculos por sí solo, con la misma rutina que ejecuta el simulador.`,saufbh:`Cuando nada refleja el ping, el HC-SR04 mantiene Echo en alto unos 38 ms (la cifra de la hoja de datos; algunos módulos lo mantienen más). Eso supera el tiempo límite de 30 ms, así que pulseIn() devuelve 0. El evitador lo cuenta como 400 cm, «libre», no como «tocando». Su haz es estrecho, así que el coche puede engancharse en una esquina que nunca vio: una lectura que deja de cambiar mientras las ruedas empujan le indica que está atascado. Y cuando se bloquea otra vez justo después de un giro, gira una vez más en el mismo sentido en vez de volver: en una esquina, si no, giraría a la izquierda, a la derecha, a la izquierda para siempre.`,"11hew0t":`ledcAttach() y ledcWrite(pin, duty) son la API de arduino-esp32 3.x; las llamadas antiguas ledcSetup() y ledcAttachPin() de la 2.x ya no compilan. El haz del sensor es estrecho, así que en Auto el coche puede engancharse en una esquina que nunca vio: una lectura que deja de cambiar mientras las ruedas empujan le indica que está atascado. Y cuando se bloquea otra vez justo después de un giro, gira una vez más en el mismo sentido en vez de volver: en una esquina, si no, giraría a la izquierda, a la derecha, a la izquierda para siempre.`,"3zk06m":`En el Arduino IDE, elige Tools → Board → Arduino UNO y el puerto correcto. Los dos sketches usan la librería Servo, que viene con el IDE.`,j0z2nr:`Levanta el coche para que las cuatro ruedas no toquen la mesa. Sube la prueba de cableado, enciende la batería y abre el Serial Monitor a 115200 baudios. Observa cómo ocurre cada línea numerada: LED y pitido, cabeza a la derecha, a la izquierda y al centro, y luego cada lado hacia delante y hacia atrás.`,"1dz2oap":`Corrige lo que no coincidiera (mira la lista de abajo). Luego sube el evitador de obstáculos, desconecta el cable USB, pon el coche en el suelo y enciéndelo: espera dos segundos y arranca.`,"4czqhs":`Cambia TURN_MS en el sketch hasta que cada giro sea más o menos un cuarto de vuelta en tu suelo.`,rgjhux:`En el Arduino IDE, añade https://espressif.github.io/arduino-esp32/package_esp32_index.json en File → Preferences → Additional boards manager URLs. Luego instala «esp32 by Espressif Systems» versión 3.x desde el Boards Manager y elige ESP32 Dev Module.`,"118rr9r":`Desde el Library Manager, instala la última «WebSockets» de Markus Sattler y «ArduinoJson» versión 7 de Benoit Blanchon.`,nbb8bl:`Sube el código, luego levanta el coche para que las cuatro ruedas no toquen la mesa y enciende la batería. Conéctate a la red Wi-Fi «RoboKit» (contraseña drive1234), ve al paso 10 y conecta desde Ajustes → Coche real (Wi-Fi del ESP32).`,srtywe:`Prueba cada control por turno: LED, zumbador, el deslizador del servo y luego W A S D. Si un lado gira al revés, mira la lista de abajo. Luego pon el coche en el suelo, prueba Auto y cambia TURN_MS hasta que cada giro sea más o menos un cuarto de vuelta.`,sp50jr:`No se enciende nada al encender`,"1gg4m0p":`Apaga. Comprueba que las celdas estén cargadas y bien orientadas, que los cables rojos estén bajo el tornillo + de la clavija y que el interruptor esté cableado entre su pin central y un pin exterior.`,"9crnd5":`Un lado gira al revés en la prueba`,"1mf4jfi":`Intercambia los dos cables de ese lado en su borne de tornillo: MOTOR-A es el lado izquierdo, MOTOR-B el derecho.`,"1gcvytv":`Una rueda gira contra su compañera`,"76bppn":`Intercambia los dos cables de ese motor donde están retorcidos con los del otro motor.`,kakgt9:`La línea 3 mueve las ruedas de la derecha`,"95tfvz":`Los dos pares de cables dupont están cruzados: A-IA / A-IB van a D11 / D12, B-IA / B-IB a D5 / D6.`,"1yvpqg9":`La cabeza mira primero a la izquierda`,"3fc0ov":`Algunos servos giran al revés: intercambia 20 y 160 en los sketches.`,"1ymivbo":`La distancia es siempre 0.0 cm`,"1wzcqly":`No vuelve ningún eco. Comprueba que Trig esté en D4 y Echo en D3, y que el VCC y el GND del sensor estén en un pin V y un pin G. También lee 0 cuando no hay nada a menos de unos 4 m.`,lg1f33:`El UNO se reinicia cuando arrancan los motores`,gp3cr0:`La tensión de la batería cae: recarga las celdas. Un condensador de 470–1000 µF entre V y G en el shield (cuidado con su polaridad) ayuda a la alimentación de 5 V a superar las caídas.`,"13n04wo":`El coche zumba pero no gira sobre sí mismo`,y7q52i:`Girar arrastra los cuatro neumáticos de lado y necesita más empuje que ir recto: sube SPIN hacia MAX_PWM y recarga las celdas.`,hvphiw:`Se desvía hacia un lado`,ittf4s:`No hay dos motores iguales. Frena el lado más rápido: para un coche que se desvía a la derecha, drive(CRUISE - 10, CRUISE).`,"19do8xl":`La subida se queda en «Connecting…»`,hn5crr:`Mantén pulsado el botón BOOT del DevKit hasta que empiece la subida, y comprueba que el cable USB transmita datos, no solo corriente.`,"144ggw6":`RoboKit no se conecta`,"1wm6oj5":`Un lado gira al revés`,"1buhj6h":`Izquierda y derecha están cambiadas`,"1s6olzj":`Los dos pares de cables dupont están cruzados: A-IA / A-IB van a GPIO 26 / 27, B-IA / B-IB a GPIO 33 / 25.`,svln7p:`En Auto, la cabeza mira primero a la izquierda`,"1ki0m9i":`Algunos servos giran al revés: intercambia 20 y 160 en autoStep().`,"6xg3a":`La distancia es siempre 400 cm`,"7himiv":`No vuelve ningún eco. Comprueba que Trig esté en GPIO 32, que Echo llegue a GPIO 35 a través del divisor y que el VCC del sensor esté en un pin de 5 V. También lee 400 cuando no hay nada a menos de unos 4 m.`,ksb87p:`El zumbador no suena`,"9czfii":`Comprueba las patas del transistor con su hoja de datos (el orden cambia según el tipo) y que el + del zumbador esté en un pin de 5 V.`,igpqu0:`El ESP32 se reinicia cuando arrancan los motores`,owaty5:`La tensión de la batería cae: recarga las celdas. Un condensador de 470–1000 µF entre un pin de 5 V y G (cuidado con su polaridad) ayuda a la alimentación a superar las caídas.`,"1u5gnnb":`Girar arrastra los cuatro neumáticos de lado y necesita más empuje que ir recto: sube la velocidad y recarga las celdas.`,uak3xr:`1 · Prueba de cableado`,"1jz093b":`2 · Evitador de obstáculos`,"129dlzg":`Firmware`,ussxe7:`Simulación`,"17ssthc":`Conduce`,bmzqy4:`El coche simulado lleva las mismas piezas que el tuyo. Condúcelo por la pista de pruebas y luego pasa a Auto: ejecuta la misma rutina que el sketch del evitador de obstáculos. Se para y pita ante un obstáculo, mira a derecha e izquierda, gira hacia el lado con más espacio y da marcha atrás cuando está atascado.`,"189d210":`El coche simulado responde a las mismas órdenes que RoboKit envía a tu ESP32, y Auto ejecuta la misma rutina que el firmware. Cuando tu coche esté montado, cámbiate a él en Ajustes → Coche real (Wi-Fi del ESP32).`,olmdkx:`Rueda, 65 mm`,psly3z:`Tracción`,vffqvh:`Un neumático de goma sobre una llanta de plástico. Su buje tiene un alojamiento con dos caras planas que encaja en el eje de salida del motor TT, así que la rueda no puede patinar. Cuando el coche gira sobre sí mismo los neumáticos se arrastran de lado, así que el agarre importa.`,jq4v4c:`Buje`,mq93xq:`alojamiento de doble cara plana para el eje del motor TT`,"1cgpuek":`Distancia por vuelta`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Motor reductor TT`,m5llum:`Un pequeño motor DC con escobillas que mueve una reductora de plástico 1:48. Invierte la corriente y la rueda gira al revés; baja la tensión media con PWM y va más despacio.`,"525amd":`Tensión`,"226us9":`Relación de reducción`,jpnnsq:`≈ 200 rpm a 6 V, sin carga`,"1dw4k8q":`Corriente`,"1p9wnb6":`≈ 150 mA sin carga · hasta ≈ 1.5 A bloqueado a 6 V`,cdauuh:`Par de bloqueo`,"1gzxf67":`≈ 0.8 kg·cm a 6 V`,ign4wl:`Cuerpo`,mad9cv:`Eje`,"14e36jb":`Ø 5.5 mm con dos caras planas separadas 3.7 mm, sale por ambos lados`,feutd2:`Montaje`,"183nrmx":`dos agujeros de Ø 3 mm separados 17.5 mm, 20 mm por detrás del eje`,"108seeu":`Soporte de motor`,"1mquwkf":`Chasis`,"10qeeg1":`Una pieza de acrílico en forma de T. Su vástago sube a través de la placa inferior junto a la reductora y su cabeza queda debajo, así que no puede salirse. Va uno a cada lado de un motor, y dos pernos largos atraviesan los dos soportes y los dos agujeros de montaje de la reductora.`,"1kk17cw":`Material`,"1me4wyg":`acrílico`,st0e1p:`Por motor`,"8uzq1j":`2 soportes · 2 × pernos M3 × 30 + tuercas`,"1am47c9":`Montaje`,v6cwyh:`desde debajo de la placa: el interior en una ranura, el exterior en una muesca del borde`,"723pu9":`Lleva los cuatro motores y los ocho separadores de la placa intermedia. Una ranura y una muesca en su borde junto a cada motor alojan los dos soportes de ese motor.`,"1n7meho":`Tamaño (este modelo)`,r4lxco:`El suelo de la electrónica. La ranura larga del centro deja subir los cables de los motores desde abajo, y el hueco rectangular delantero aloja el servo; la muesca de su extremo es para el cable del servo.`,"11vqw8c":`25 mm por encima de la placa inferior`,"1957t19":`Placa superior`,"2ljc6y":`Una placa de media longitud en la parte trasera que lleva el pack de baterías, el interruptor y el zumbador por encima de la electrónica.`,"1ytak7b":`1.5 cm por encima de la placa intermedia`,"1ey525v":`Separador de latón, M3`,"7je4w9":`Separadores hexagonales con rosca en los dos extremos. Mantienen separadas las placas y elevan las placas de circuito sobre el acrílico para que nada de su cara inferior toque.`,"1t2znv5":`Rosca`,i9dhsi:`M3, hembra–hembra`,"1cazjzs":`placa inferior → intermedia (libra los motores de 22 mm)`,rni6ay:`placa intermedia → superior`,"1dz3bjd":`placa del controlador`,"1erre2c":`Tornillos`,"7fsd49":`un M3 × 6 mm en cada extremo, 32 en total`,pmsrct:`Cables de los motores`,h0ivdz:`Un cable rojo y uno negro de cada motor: el rojo en la lengüeta más cercana al centro del coche, el negro en la más cercana a la rueda. Los dos motores de cada lado van cableados en paralelo a un canal del driver, rojo con rojo y negro con negro, así que siempre giran juntos.`,"148isqp":`unos 15 cm cada uno`,"88dh10":`Par izquierdo`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Par derecho`,"1il2rct":`MOTOR-B`,"4iibl6":`¿Un lado va al revés?`,"1p9lbgb":`intercambia sus dos pares en el borne`,"2380z5":`¿Una rueda contra su compañera?`,h5sbfv:`intercambia los dos cables de ese motor`,"19qn9l6":`Driver de motores L9110S`,"82whm4":`Electrónica`,"12ibf8u":`Dos chips de puente H L9110S, uno por canal. Cada canal tiene dos entradas: IA en alto e IB en bajo gira el motor en un sentido, IA en bajo e IB en alto lo gira en el otro, y las dos iguales lo paran. PWM en una entrada fija la velocidad.`,"25ul91":`Alimentación (VCC)`,m2phlf:`800 mA por canal (1.5–2 A de pico)`,"17s6ks8":`Entradas`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · lógica de 3.3 V o 5 V`,"4swwow":`Tira de pines`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (pines en ángulo recto)`,"1xbblqt":`unos 29 × 23 mm, agujeros de montaje de Ø 3 mm (las medidas varían según el vendedor)`,"189a81e":`Una placa con microcontrolador ATmega328P. Ejecuta tu sketch, lee el sensor y decide qué hacen los motores.`,"1ebaepz":`ATmega328P a 16 MHz`,"16qkmtv":`Nivel lógico`,eslzkd:`Pines PWM`,oopaku:`Memoria`,"8hfwsd":`32 KB de flash · 2 KB de RAM`,"1jzh7y5":`Entrada de alimentación`,"1vbs2jm":`7–12 V en la toma DC (recomendado)`,"1hxwxrt":`Corriente por pin`,xms582:`20 mA recomendado · 40 mA máximo absoluto`,"1n28mf4":`Se enchufa encima del UNO y lleva cada pin a una tira de 3 pines G / V / S (tierra, 5 V, señal), para que un servo o sensor se conecte directamente con su propia tierra y alimentación.`,e8ir2h:`Tiras de pines`,d0uaj4:`D0–D13 y A0–A5, cada uno G · V · S`,"1iy90zn":`Pines V`,ohp32m:`5 V del UNO mientras el jumper SEL esté puesto`,"1y4aysj":`Sin el jumper`,gi4ocs:`V viene del borne de tornillo del shield`,"1thlwjq":`Precaución`,"1fzsig9":`nunca alimentes el borne de tornillo con el SEL puesto`,"1kft85q":`Extras`,"1e4238k":`Tiras I²C y serie`,"1jeelmn":`ESP32 DevKit + placa de expansión`,"8jd2d6":`Un microcontrolador de doble núcleo con Wi-Fi y Bluetooth, asentado en una placa de expansión que añade una toma DC con regulador y una tira G / V / S para cada pin.`,"1inmx8d":`Módulo`,qx458t:`ESP32-WROOM-32 · hasta 240 MHz`,"7ra2ga":`3.3 V, no tolera 5 V`,"1chl2hi":`cualquier pin de salida (LEDC)`,"7fk3dd":`Inalámbrico`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V en la toma DC (comprueba tu placa)`,yzyhje:`3.3 V o 5 V, según un jumper`,"7wntef":`Microservo SG90`,mni0ct:`Un pequeño motor, una reductora y un sensor de posición en una misma caja. Espera un pulso cada 20 ms (50 Hz); el ancho del pulso fija el ángulo: 1.5 ms es el centro, y unos 0.5–2.4 ms cubren de 0° a 180°.`,wvoosj:`Par`,"1e13gca":`≈ 0.1 s por cada 60°`,"1yo9wk7":`Tamaño · peso`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Cables`,"1qalf36":`marrón GND · rojo V+ · naranja señal`,"1bshntj":`Soporte de servo para HC-SR04`,"1yr5sge":`Se atornilla al brazo del servo y sujeta el HC-SR04 por dos de sus agujeros de esquina, así el sensor gira con el servo y su haz se mantiene horizontal.`,"1t4m9bk":`Fijación`,mnle4w:`tornillos del brazo del servo`,"1yzxd81":`Sujeta`,"1fp9bdu":`el HC-SR04 por dos de sus agujeros de esquina, sobre espaciadores`,"1yozvc2":`Otros tipos`,"16fhes5":`muchos soportes sujetan el sensor por sus dos transductores`,c8gdr7:`Un pulso de 10 µs en Trig hace que un transductor emita ocho ciclos de 40 kHz; el otro escucha. Echo se mantiene en alto mientras el sonido tarda en ir y volver, así que cm = µs ÷ 58 (343 m/s, a la mitad).`,"198uyr6":`Alcance`,"3xsn4q":`Haz`,"1gw4v0v":`menos de 15°`,"1oy2zwu":`Alimentación`,"1m7niep":`Frecuencia de ping`,"7gsn1j":`uno cada 60 ms o más lento`,npm5w4:`Pines (frente, izquierda → derecha)`,pyp646:`VCC · Trig · Echo · GND con los pines abajo; montado con los pines arriba, como aquí: GND · Echo · Trig · VCC`,cr1wqh:`Pack Li-ion 2 × 18650`,"1fdnj4z":`Dos celdas en serie: 8.4 V cargadas, 7.4 V nominales, unos 6 V descargadas. Usa celdas protegidas, no las cortocircuites nunca y cárgalas en un cargador de Li-ion adecuado.`,w63ube:`7.4 V nominales (6–8.4 V)`,serueh:`Capacidad`,"1lup9sh":`2000–3500 mAh (celdas originales)`,"7l22en":`Portapilas`,"1ka7i4l":`2 posiciones, en serie`,"1h1ba5m":`las celdas protegidas son unos mm más largas; comprueba que caben`,h4px5m:`Interruptor`,bs7ocz:`Corta el cable + de la batería, así se apaga todo el coche. Se cablea entre su pin central y un pin exterior: el cable rojo del portapilas en uno y el cable hacia la clavija en el otro. Va de lado sobre cinta de espuma en el borde izquierdo de la placa superior, con la palanca hacia fuera, donde un dedo puede alcanzarlo.`,"1m2zofh":`Tipo`,"69jc9h":`interruptor deslizante SPDT usado como encendido/apagado`,w3vkqt:`Pines`,"1owufyi":`tres en fila: exterior · común · exterior`,fph5dc:`Corriente nominal`,"1bpycfc":`elige uno de ≥ 2 A DC`,k3s7zg:`Zumbador activo, 5 V`,"177ed2m":`Señales`,jfbt4g:`Lleva su propio oscilador dentro: pon el pin en HIGH y pita con un tono fijo, sin necesidad de código tone(). Consume hasta unos 25–30 mA: dentro del máximo absoluto de 40 mA del pin pero por encima de los 20 mA que se suelen recomendar, así que conmutarlo con un transistor NPN es la costumbre más suave.`,xscire:`Lleva su propio oscilador dentro: aliméntalo y pita con un tono fijo. Los zumbadores activos de 5 V están especificados a partir de unos 3.5–4 V, así que un pin de 3.3 V no puede hacerlo funcionar de forma fiable. Aquí se alimenta del pin V de 5 V y lo conmuta un transistor NPN, controlado por el GPIO 21.`,"1p7q9i9":`Tono`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Tensión nominal`,"2tl42a":`5 V (funciona desde ≈ 3.5–4 V, según el fabricante)`,"1udh5u4":`≈ 25–30 mA a 5 V`,"1xat3vm":`separados 7.6 mm`,"1yzktex":`Polaridad`,"1tmcwg9":`pin más largo / «+» arriba = +`,i8lb7k:`LED rojo de 10 mm`,"513nhj":`La corriente va de la pata larga (ánodo, +) a la corta (cátodo, −, junto a la parte plana del borde). Siempre necesita una resistencia en serie. Aquí va de lado junto a la esquina delantera izquierda del controlador, iluminando hacia la izquierda del coche.`,"17jikfo":`Tensión directa`,"1g61wql":`20 mA máx.`,u532rf:`Resistencia de 220 Ω`,"17qhgqf":`Limita la corriente del LED: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Las bandas de color son rojo, rojo, marrón: 2, 2 y × 10 = 220 Ω.`,"1kwszon":`Limita la corriente del LED: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Las bandas de color son rojo, rojo, marrón: 2, 2 y × 10 = 220 Ω.`,zzpczz:`Bandas`,"7ytjo4":`rojo · rojo · marrón · oro`,"1llx3uw":`Tolerancia`,"3389ey":`Divisor de Echo · 1 kΩ + 2 kΩ`,i8pnlw:`La salida Echo del HC-SR04 llega a 5 V, pero los pines del ESP32 admiten como mucho 3.3 V. Dos resistencias en serie de Echo a tierra forman un divisor: el GPIO lee la tensión en la de 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Bandas de 1 kΩ`,"89urq0":`marrón · negro · rojo · oro`,"1ypqwgn":`Bandas de 2 kΩ`,"1ywrkmt":`rojo · negro · rojo · oro`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ de GPIO 35 a G`,aarp77:`Necesario para`,"15e8vss":`solo ESP32`,"1aqlq1n":`Transistor del zumbador · NPN + 1 kΩ`,vudz42:`Un transistor NPN funciona como interruptor: una pequeña corriente en su base deja pasar otra mayor del colector al emisor. El GPIO 21 controla la base a través de 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, de sobra para conmutar los ≈ 30 mA del zumbador desde el pin de 5 V.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 o un NPN similar`,"1tlwyig":`Colector`,"18vf2cp":`− del zumbador`,"19phq7s":`Base`,hrttng:`1 kΩ → S de GPIO 21`,"10ztoj1":`Emisor`,"1m0unsb":`G de GPIO 21`,"16l0jzg":`Patas`,v4q23:`comprueba el patillaje en su hoja de datos`,gy95h:`Cable de conexión`,"170hkbj":`Cable trenzado rojo y negro para los cables de los motores. Córtalo a medida sobre la marcha.`,"19d4ccc":`Rojo`,ch832v:`la lengüeta más cercana al centro del coche, en cada motor`,bxogn8:`Negro`,"1xdely8":`la lengüeta más cercana a la rueda`,"114bxvb":`Cables dupont hembra–hembra`,tq3ghm:`Cables Dupont con un conector en cada extremo que encajan en pines de 2.54 mm. Las entradas del driver y el sensor usan un dupont entero por pin. Cortado en dos, un dupont da cables con conector en un solo extremo: para las piezas que se sueldan (el LED, el zumbador) y para la alimentación del driver, cuyos otros extremos van bajo los tornillos de la clavija.`,xe6ekx:`Paso`,terfe0:`15 cm (los de 20 cm también valen: dejan bucles más grandes)`,q9r4h7:`Usados enteros`,"16oowgw":`8: cuatro entradas del driver, cuatro pines del sensor`,"1rf1gzr":`7: cuatro entradas del driver, tres pines del sensor`,onu7hf:`Cortados`,"38aacf":`4: un rojo y un negro por la mitad para los cables del LED y del zumbador, un rojo y un negro a 12.5 cm de un extremo para la alimentación del driver`,"3iidc0":`6: un rojo y un negro por la mitad para los cables del LED y del zumbador, un naranja por la mitad para la base del transistor, un rojo y un negro a 11 cm de un extremo para la alimentación del driver, y el cable Echo del sensor para su divisor`,"14fe75h":`Cables dupont · sensor ultrasónico`,f96u6l:`Cuatro cables dupont desde la tira de pines del sensor, que está arriba, en arco hacia atrás hasta el shield. Cualquier pin V y cualquier pin G valen para VCC y GND: se usan los más cercanos, así los cuatro cables salen en abanico uno junto a otro.`,tuihok:`Cuatro cables desde la tira de pines del sensor, que está arriba, en arco hacia atrás hasta la placa de expansión. Echo es una señal de 5 V, así que pasa por un divisor de 1 kΩ / 2 kΩ (soldado en su dupont, bajo termorretráctil) antes de llegar al GPIO de 3.3 V.`,ftyyiy:`V de D4`,"1xuokt7":`Trig`,o3rtpx:`S de D4`,gi87tw:`Echo`,m5ulv4:`S de D3`,y9urxb:`G de D2`,"1n4125d":`V de GPIO 32 (a 5 V)`,p5iwlb:`S de GPIO 32`,"1aj3mnm":`1 kΩ → S de GPIO 35 · 2 kΩ de ahí a su G`,p0bbcd:`G de GPIO 34`,"1kn37ri":`Cables dupont · driver de motores`,oiporr:`Las cuatro entradas del driver. Cada par controla un lado del coche: IA lleva su velocidad, en un pin PWM, e IB su dirección.`,z48w8g:`Las cuatro entradas del driver, cada una en un pin con PWM. Cada par controla un lado del coche.`,"11ubulz":`A-IA / A-IB (izquierda)`,jf4uze:`B-IA / B-IB (derecha)`,"15oeqsr":`Cable del servo`,wowqjs:`El propio cable de tres hilos del servo. Baja por el hueco y sube por la ranura de al lado, va hacia atrás por la placa junto al controlador y llega a la tira trasera; lo que sobra se dobla bajo la placa. Su conector de 3 vías encaja de una vez en una tira G / V / S: marrón en G.`,v89fad:`El propio cable de tres hilos del servo. Baja por el hueco y sube por la ranura de al lado, va hacia atrás por la placa junto al controlador y llega a la tira trasera; lo que sobra se dobla bajo la placa. Su conector de 3 vías encaja de una vez en una tira G / V / S: marrón en G. La fila V tiene que estar a 5 V.`,r6nyn:`Marrón`,"1u2gqme":`Naranja (señal)`,"1qoi1mz":`S de A5`,ovg5ed:`S de GPIO 23`,"1uovlnp":`Cables del LED`,"1mffxae":`Medio dupont rojo y medio negro, soldados al LED con un conector en el otro extremo. El ánodo va a través de la resistencia de 220 Ω a un pin de señal; el cátodo va a tierra.`,elp8sy:`Ánodo (vía 220 Ω)`,k62hvj:`S de D13`,ilk009:`Cátodo`,k48vv7:`G de D13`,tbj8zu:`S de GPIO 13`,imqrdy:`G de GPIO 13`,"1indwkw":`Cables del zumbador`,"1c2cbqo":`Medio dupont rojo y medio negro soldados a los pines del zumbador. Pon el cable + en HIGH para pitar.`,epsmo4:`El zumbador va entre el pin V de 5 V y el transistor. Pon el GPIO 21 en HIGH y el transistor conecta el − del zumbador a tierra, así que pita.`,"1rigupw":`S de A0`,"1yvwce0":`G de A0`,"1tndblu":`V de GPIO 21 (5 V)`,i73cl5:`colector del transistor`,a4pty4:`Base (vía 1 kΩ)`,obgy0f:`S de GPIO 21`,g663eg:`Cableado de alimentación`,wp3j1m:`Todo se une en una clavija DC con dos bornes de tornillo, metida en la toma DC del UNO. El + de la batería llega a su borne + a través del interruptor; el − de la batería va directo a su borne −. Un segundo cable rojo y un segundo negro bajo los mismos dos tornillos llevan la tensión de la batería a los pines VCC y GND del driver. El driver no puede alimentarse de los pines de 5 V del shield: los alimenta el regulador del UNO, que da como mucho unos cientos de mA.`,"1gazt2h":`Todo se une en una clavija DC con dos bornes de tornillo, metida en la toma DC de la placa de expansión. El + de la batería llega a su borne + a través del interruptor; el − de la batería va directo a su borne −. Un segundo cable rojo y un segundo negro bajo los mismos dos tornillos llevan la tensión de la batería a los pines VCC y GND del driver. El driver no puede alimentarse de los pines de 5 V de la placa: los alimenta su regulador, que da como mucho unos cientos de mA.`,"1wuyp3l":`+ de la batería (con interruptor)`,"161fdmk":`− de la batería = GND`,"6j9255":`Clavija`,"1qkac6a":`barril de 5.5 × 2.1 mm, centro +, con bornes de tornillo`,"1s864ea":`Bajo cada tornillo`,wj14kx:`dos cables: uno de la batería, otro hacia el driver`,oz5l6a:`Evitador de obstáculos`,zj0mwn:`Medir la distancia`,"9jogsy":`En cada vuelta de loop() se lanza un ping con el sensor. El sketch también anota cuándo cambió la lectura por última vez en más de {changeCm} cm: una lectura que no cambia mientras las ruedas empujan es la señal de que el coche está atascado.`,"1va2b8a":`¿Camino libre?`,yssn5p:`¿Está libre el camino?`,zou1hc:`Libre significa que no hay nada a menos de {stopCm} cm (STOP_CM) y que la lectura sigue cambiando. Entonces el coche sigue adelante y vuelve a preguntar {pingMs} ms después.`,"164owbk":`Seguir adelante`,"2guryp":`LED apagado, los dos lados hacia delante a CRUISE y una espera de {pingMs} ms: el sensor necesita ese tiempo entre dos pings. Luego, otra vuelta.`,l1vybm:`Parar
LED encendido · pitido`,ywa890:`Parar, LED encendido, un pitido corto`,"17krb65":`Bloqueado o atascado: los motores se paran, el LED se enciende y el zumbador suena durante {beepMs} ms.`,"1njcbjw":`¿Atascado?`,"6b9vj0":`¿Atascado en algo que el haz no vio?`,"12aymoo":`El haz del sensor solo mide unos 15° de ancho, así que el coche puede engancharse en una esquina que nunca vio. Si la lectura no ha cambiado más de {changeCm} cm durante {stuckMsS} aunque el camino parecía libre, el coche está atascado. (Sin ningún eco, 400, nunca cuenta: el espacio abierto no es «atascado».)`,"7k6lib":`Retroceder`,ooiwv8:`Se aparta de lo que lo retiene durante {backOffMsS} y solo entonces mira alrededor.`,"1d4sv1w":`Mirar a la derecha y luego a la izquierda`,"18crqcc":`La cabeza gira a {lookRight}° (derecha) y a {lookLeft}° (izquierda). Cada vez se le dan al servo {settleMsS} para llegar antes de leer el sensor; las dos lecturas se imprimen.`,"1r9o4nf":`¿Hay espacio para girar?`,"122yr22":`Si ningún lado tiene {tightCm} cm (TIGHT_CM), aquí no hay espacio para girar.`,"1i7u6tc":`Marcha atrás y mirar otra vez`,"1ik4v71":`Dar marcha atrás y volver a mirar`,a0a741:`Encerrado: da marcha atrás durante {backMsS} y desde ahí vuelve a mirar a derecha e izquierda, tantas veces como haga falta.`,"1yfjvg4":`¿Acaba de girar?`,"2jbjim":`¿Bloqueado otra vez justo después de un giro?`,"3dv25u":`La cabeza vuelve al centro. Después: si el último giro terminó hace menos de {againMsS}, el coche apenas se ha movido desde que giró.`,"1steplx":`Otra vez en el mismo sentido`,kn4k3y:`Girar otra vez en el mismo sentido`,"1k7wpmb":`Girar al revés solo lo devolvería a donde estaba: en una esquina giraría a la izquierda, a la derecha, a la izquierda para siempre. Así que sigue girando en el sentido en que giró la última vez, digan lo que digan las dos lecturas.`,"1lf2d81":`El lado con más espacio`,"1u19y2l":`Girar hacia el lado con más espacio`,"1n1zre5":`A la izquierda si la lectura de la izquierda es al menos tan grande como la de la derecha; si no, a la derecha.`,"5j8yhm":`Girar`,"4h9f4g":`Los dos lados giran en sentidos opuestos durante TURN_MS ({turnMs} ms, más o menos un cuarto de vuelta: ajústalo a tu suelo). Luego el coche se para, recuerda hacia dónde giró y cuándo, y loop() empieza otra vez desde arriba.`,mz8bk9:`Modo Auto`,rg9t88:`Diez veces por segundo loop() lanza un ping con el sensor y guarda la lectura en distance (que se envía a RoboKit al mismo tiempo). En el modo Auto, autoStep() decide luego qué hacer con ella.`,"15ai7e9":`Bloqueado significa que hay algo a menos de {stopCm} cm (STOP_CM). La lectura puede tener hasta {sampleMsS} de antigüedad, así que justo después de un giro espera {freshMs} ms a una tomada mirando en la nueva dirección. Si no, el coche sigue avanzando.`,"1wwbbaz":`Mientras avanza, dir vale "forward": el final de loop() lo convierte en las velocidades de los dos motores, a la velocidad que ha fijado RoboKit.`,q8ujdx:`El haz del sensor solo mide unos 15° de ancho, así que el coche puede engancharse en una esquina que nunca vio. Si la lectura no ha cambiado más de {changeCm} cm durante {stuckMsS} mientras avanzaba, el coche está atascado: retrocede antes de mirar alrededor. (Sin ningún eco, 400, nunca cuenta: el espacio abierto no es «atascado».)`,"1e83w8t":`La cabeza gira a {lookRight}° (derecha) y luego a {lookLeft}° (izquierda). Cada lectura se toma cuando el servo ha tenido tiempo de llegar, y la cabeza vuelve al centro.`,"1pjappa":`Si el último giro terminó hace menos de {againMsS}, el coche apenas se ha movido desde que giró. (Activar Auto empieza de cero: turnedAt vale entonces 0.)`,pjp20w:`Girar al revés solo lo devolvería a donde estaba: en una esquina giraría a la izquierda, a la derecha, a la izquierda para siempre. Así que goLeft se deja como está y el coche gira en el sentido en que giró la última vez, digan lo que digan las dos lecturas.`,ihilws:`Los dos lados giran en sentidos opuestos durante TURN_MS ({turnMs} ms, más o menos un cuarto de vuelta: ajústalo a tu suelo). Luego el LED se apaga, se anota la hora y el coche vuelve a avanzar.`,"1k1y69x":`4× motor TT`,"15bpusl":`8× soporte de motor`,dgwrs0:`Tornillos, tuercas y pernos M3`,"1mkf3n0":`4× rueda, 65 mm`,"19aemsl":`Driver L9110S`,"123jzux":`almohadilla de espuma`,a4iz5j:`Placa de expansión ESP32`,"1al7iyf":`soporte del sensor`,a89ttz:`Servo SG90`,"1alynuo":`brazo`,"1pbblc6":`Portapilas 2 × 18650`,muur5i:`2× celda 18650`,"1t10ooq":`interruptor`,"7h9qib":`zumbador activo`,"1uw5qdo":`clavija DC`,"1l9u4j2":`16× separador M3`,hiufn9:`cable de conexión`,"1w4hkux":`20× cables dupont (H–H, 15 cm)`,"1onzquf":`placa inferior`,"1h4bzq9":`placa intermedia`,myp2cd:`placa superior`,pu413r:`Los navegadores bloquean ws:// desde una página https:// — ejecuta RoboKit en tu ordenador (npm run dev) para llegar al coche`,tqkecz:`Esta página se sirve por https, así que el navegador no le deja abrir ws:// hacia el coche. Para conducir el coche real, ejecuta RoboKit en tu ordenador (npm install y luego npm run dev) y abre http://localhost:5173.`,vqmrol:`Tu ordenador debe estar en la red “RoboKit”, y RoboKit debe estar abierto por http://, no por https://: los navegadores bloquean ws:// desde páginas seguras, así que una copia alojada en la web no puede llegar al coche. Ejecútalo en tu ordenador (npm install mientras aún tengas internet, luego npm run dev) y abre http://localhost:5173.`};export{e as default};